<template>
  <div>
    <input type="file" ref="fileInput" @change="handleFileUpload" hidden />
    <div class="row items-center justify-end q-pa-sm">
      <f-btn :label="$t('upload')" @click="triggerFileUpload" />
    </div>
    <div class="row full-width q-pl-sm q-pr-sm">
      <div class="col-12">
        <DocBitsTable
          :rows="Array.isArray(fileList) ? fileList : []"
          :columns="docBitsColumns"
          row-key="id"
          table-id="supplier_registration_reference_documents_table"
          :loading="loading"
          :features="{
            sorting: false,
            filtering: false,
            selection: false,
            bulkActions: false,
            rowActions: true,
            resizable: false,
            pagination: false,
            columnReorder: false,
            stickyLastColumn: true,
          }"
          :row-actions="documentRowActions"
          no-data-label="no_record_found"
          flat-style
          @row-action="handleRowAction"
        >
          <template #body-cell-name="{ row }">
            {{ row.document_name }}
            <q-icon
              name="visibility"
              size="18px"
              class="cursor-pointer q-pl-sm color-primary"
              @click="viewFile(row)"
            >
              <q-tooltip>{{ $t('preview_file') }}</q-tooltip>
            </q-icon>
          </template>
        </DocBitsTable>
      </div>
    </div>
  </div>

  <!-- popup view file -->
  <q-dialog v-model="openViewFile" persistent>
    <q-card style="width: 700px; max-width: 800px">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('Document') }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <div class="col-12 mt-10 q-pa-sm">
        <iframe
          v-if="!skeletonLoad"
          id="preview_frame"
          :src="iframe_path"
          title="file preview"
          width="100%"
          height="550px"
        ></iframe>
        <q-skeleton
          v-else
          style="width: 100%"
          :animated="false"
          width="100%"
          height="550px"
          class="custom-skeleton"
        ></q-skeleton>
      </div>
    </q-card>
  </q-dialog>

  <!-- delete confirm dialog -->
  <q-dialog v-model="confirmDelete" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn :label="$t('delete')" v-close-popup @click="onDeleteFile" />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-inner-loading :showing="loading" class="z-index-2">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { copyToClipboard } from 'quasar';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions';
import helperMixin from 'src/mixins/helperMixin';
import { supplierRegistrationReferenceDocumentsApiService } from 'src/services';
import { DOC2API_URL, getAuthorizationToken } from 'pages/APIs';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { supplierRegistrationReferenceDocumentsStore } from 'src/store/Settings/supplier_registration_reference_documents.store';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type {
  RowActionItem,
  UnifiedTableColumn,
} from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: { DocBitsTable },
  async mounted() {
    await this.getFiles();
  },
  data() {
    return {
      confirmDelete: ref(false),
      openViewFile: ref(false),
      docBitsColumns: [
        {
          name: 'name',
          label: this.$t('name'),
          field: 'document_name',
          align: 'left',
        },
        {
          name: 'file_type',
          label: this.$t('file_type'),
          field: 'document_type',
          align: 'left',
        },
      ] as UnifiedTableColumn[],
      documentRowActions: [
        { key: 'copy', label: 'copy', icon: 'content_copy' },
        {
          key: 'delete',
          label: 'delete',
          icon: 'delete',
          color: 'negative',
          separator: true,
        },
      ] as RowActionItem[],
      file_id: ref(''),
      iframe_path: ref(''),
      skeletonLoad: ref(false),
    };
  },
  methods: {
    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'copy') {
        this.copyFile(row);
      } else if (action === 'delete') {
        this.confirmDialog(row.id);
      }
    },
    async viewFile(row: any) {
      this.openViewFile = true;
      await this.getPreviewFile(row);
    },
    async getPreviewFile(row: any) {
      try {
        this.skeletonLoad = true;
        const bearerToken = await getAuthorizationToken();
        const token = bearerToken.split(' ')[1];
        const id = row.id as string;
        const path = row.document_path as string;
        const data = {
          id: id,
          path: path,
          token: token,
        };
        const response =
          await supplierRegistrationReferenceDocumentsApiService.previewFile(
            data,
          );
        const url = response.config.url as string;
        this.iframe_path = url;
      } catch (error: any) {
        logError(error);
      } finally {
        this.skeletonLoad = false;
      }
    },
    documentNameWithoutExtension(name: string) {
      return name.substring(0, name.lastIndexOf('.')) || name;
    },
    buildFileUrl(data: dynamicObj) {
      return `${DOC2API_URL}/resource/get_file/${data.id as string}?path=${data.path as string}&download=false&token=${data.token as string}&org_id=${getOrgId()}`;
    },
    async copyFile(row: any) {
      try {
        const bearerToken = await getAuthorizationToken();
        const token = bearerToken.split(' ')[1];
        const id = this.documentNameWithoutExtension(row.document_name);
        const path = row.document_path as string;
        const data = {
          id: id,
          path: path,
          token: token,
        };
        const url = this.buildFileUrl(data);
        copyToClipboard(url).then(() => {
          notify.success(this.$t('copy_to_clipboard'));
        });
      } catch (error: any) {
        logError(error);
      }
    },
    triggerFileUpload() {
      (this.$refs.fileInput as any).click();
    },
    async handleFileUpload(event: any) {
      try {
        this.loading = true;
        const file = event.target.files[0];
        const response = await this.uploadReferenceDocument(file);
        if (response?.success === false) {
          throw response?.message;
        }
        await this.getFiles();
        notify.success(this.$t('upload_success'));
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },
    confirmDialog(id: string) {
      this.file_id = id;
      this.confirmDelete = true;
    },
    async onDeleteFile() {
      try {
        this.loading = true;
        const response =
          await supplierRegistrationReferenceDocumentsApiService.delete(
            this.file_id,
          );
        if (response.success === false) {
          throw response?.message;
        }
        await this.getFiles();
        notify.success(this.$t('file_deleted_successfully'));
        this.confirmDelete = false;
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    const referenceDocumentsStore =
      supplierRegistrationReferenceDocumentsStore();
    const { uploadReferenceDocument, getFiles } = referenceDocumentsStore;
    const { loading, fileList } = storeToRefs(referenceDocumentsStore);

    return {
      loading,
      uploadReferenceDocument,
      getFiles,
      fileList,
    };
  },
});
</script>
