  <div class="status-handler-container q-pa-lg">
    <q-card flat class="main-card">
      <div class="row">
        <!-- Left Panel: Workflow Statuses -->
        <div class="col-12 col-md-6 left-panel">
          <div class="panel-header">{{ $t('workflow_statuses') }}</div>
          <div :class="['status-list-section', 'q-pa-md', 'q-pt-none', { 'expanded': isForApproval }]">
            <draggable
              v-model="status_list"
              class="status-list"
              @end="onDragEnd"
            >
              <div
                v-for="(status, idx) in status_list"
                :key="status.value"
                :class="['status-item', { 'status-item-selected': indexBeingEdited === idx }]"
                @click="editStatus(idx)"
              >
                <q-icon name="drag_indicator" class="drag-handle" size="18px" />
                <span class="status-label">{{ status.label }}</span>
                <q-badge
                  v-if="status.is_for_approval"
                  class="approval-badge"
                  label="Approval"
                />
                <q-space />
                <q-icon
                  v-if="status.type === 'custom'"
                  name="delete_outline"
                  class="delete-icon"
                  size="20px"
                  @click.stop="confirmDelete(idx)"
                />
              </div>
            </draggable>
          </div>
        </div>

        <!-- Right Panel: Configure Status -->
