<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { supplier_statuses } from 'src/constants';
import { VueDraggableNext } from 'vue-draggable-next';
import { userApiService } from 'src/services';
import ConfirmDialog from 'src/supplier/pages/ConfirmDialog.vue';
export interface StatusItem {
  label: string;
  value: string;
  type?: string;
  is_for_approval?: boolean;
  admin_can_approve?: boolean;
  referer_can_approve?: boolean;
  assignee_can_approve?: boolean;
  user_groups?: string[];
}

export default defineComponent({
  name: 'SupplierStatusesHandler',
  props: ['showSpinner'],
  components: {
    draggable: VueDraggableNext,
    ConfirmDialog
  },
  data() {
    return {
      newStatus: '',
      status_list: [] as StatusItem[],
      supplier_statuses,
      isForApproval: false,
      isDefault: false,
      indexBeingEdited: -1,
      adminCanApprove: false,
      refererCanApprove: false,
      assigneeCanApprove: false,
      userGroups: [] as Array<{ label: string; value: string }>,
      selectedUserGroups: [] as string[],
      showDeleteDialog: false,
      deleteIndex: -1,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted() {
    this.initView();
    this.fetchUserGroups();
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      updateSetting,
    };
  },
  methods: {
    initView() {
      if (!this.user_settings[this.supplier_statuses]) {
        this.user_settings[this.supplier_statuses] = '[]';
      }
      if (this.user_settings[this.supplier_statuses]) {
        this.status_list = JSON.parse(this.user_settings[this.supplier_statuses]);
      }
    },

    editStatus(idx: number) {
      const selectedStatus = this.status_list[idx];
      this.newStatus = selectedStatus.label;
      this.isDefault = selectedStatus.type === 'default';
      this.isForApproval = selectedStatus.is_for_approval || false;
      this.adminCanApprove = selectedStatus.admin_can_approve || false;
      this.refererCanApprove = selectedStatus.referer_can_approve || false;
      this.assigneeCanApprove = selectedStatus.assignee_can_approve || false;
      this.selectedUserGroups = selectedStatus.user_groups || [];
      this.indexBeingEdited = idx;
    },

    async saveChanges() {
      if (!this.newStatus) {
        notify.error(this.$t('status_field_cannot_be_empty'));
        return;
      }

      if (this.indexBeingEdited === -1) {
        // No status selected - add new status at the end
        const statusToAdd: StatusItem = {
          label: this.newStatus,
          value: this.newStatus.toLowerCase().replace(/\s+/g, '_'),
          type: 'custom',
          is_for_approval: this.isForApproval,
          admin_can_approve: this.adminCanApprove,
          referer_can_approve: this.refererCanApprove,
          assignee_can_approve: this.assigneeCanApprove,
          user_groups: this.selectedUserGroups,
        };
        this.status_list.push(statusToAdd);
        this.indexBeingEdited = this.status_list.length - 1;
      } else {
        // Update existing status
        const status = this.status_list[this.indexBeingEdited];
        if (status.type !== 'default') {
          status.label = this.newStatus;
          status.value = this.newStatus.toLowerCase().replace(/\s+/g, '_');
        }
        status.is_for_approval = this.isForApproval;
        status.admin_can_approve = this.adminCanApprove;
        status.referer_can_approve = this.refererCanApprove;
        status.assignee_can_approve = this.assigneeCanApprove;
        status.user_groups = this.selectedUserGroups;
      }

      await this.saveToServer();
    },

    async saveToServer() {
      try {
        await this.updateSetting(this.supplier_statuses, JSON.stringify(this.status_list));
        notify.success(this.$t('MSG_SAVE'));
      } catch (e: any) {
        logError(e);
        notify.error('Failed to save changes');
      }
    },

    async onDragEnd() {
      // Save order after drag
      await this.saveToServer();
    },

    confirmDelete(idx: number) {
      this.deleteIndex = idx;
      this.showDeleteDialog = true;
    },

    async deleteStatus() {
      if (this.deleteIndex >= 0) {
        this.status_list.splice(this.deleteIndex, 1);

        // Clear selection if deleted item was selected
        if (this.indexBeingEdited === this.deleteIndex) {
          this.resetForm();
        } else if (this.indexBeingEdited > this.deleteIndex) {
          this.indexBeingEdited--;
        }

        this.deleteIndex = -1;
        await this.saveToServer();
      }
    },

    resetForm() {
      this.indexBeingEdited = -1;
      this.resetFields();
    },

    resetFields() {
      this.newStatus = '';
      this.isForApproval = false;
      this.isDefault = false;
      this.adminCanApprove = false;
      this.refererCanApprove = false;
      this.assigneeCanApprove = false;
      this.selectedUserGroups = [];
    },

    async fetchUserGroups() {
      try {
        const response = await userApiService.getGroups();
        if (response && Array.isArray(response)) {
          this.userGroups = response.map((group: any) => ({
            label: group.name || group.group_name,
            value: group.id || group.group_id,
          }));
        }
      } catch (e: any) {
        logError(e);
      }
    },
  },
});
</script>

