<template>
  <div>
    <div class="row q-gutter-md q-pa-sm">
      <div style="width: 30%">
        <q-card flat>
          <q-card-section>
            <q-file
              v-model="uploadFile"
              data-test="company-logo-upload"
              :label="$t('upload_logo')"
              filled
              accept=".png,.jpg,.jpeg,.webp"
              aria-placeholder="Upload Logo"
              :standout="true"
              :outlined="true"
              :counter="false"
              @update:model-value="handleUpload"
              :label-slot="!uploadFile"
            >
              <template v-slot:prepend>
                <q-icon name="attach_file" />
              </template>
              <template v-slot:append>
                <q-icon
                  name="laptop"
                  class="cursor-pointer text-primary"
                />
              </template>
              <template v-if="!uploadFile" v-slot:label>
                {{ logoObject?.desktop?.filename }}
              </template>
            </q-file>
            <q-img
              :src="logoObject?.desktop?.logo"
              class="q-mt-md"
              style="max-width: 100%; max-height: 300px; object-fit: fill"
            />
          </q-card-section>
        </q-card>
      </div>
      <div style="width: 30%">
        <q-card flat>
          <q-card-section>
            <q-file
              v-model="uploadFileMoblie"
              data-test="company-logo-mobile-upload"
              :label="$t('upload_logo')"
              filled
              accept=".png,.jpg,.jpeg,.webp"
              aria-placeholder="Upload Logo"
              :standout="true"
              :outlined="true"
              :counter="false"
              @update:model-value="handleUpload($event, 'mobile')"
              :label-slot="!uploadFile"
            >
              <template v-slot:prepend>
                <q-icon name="attach_file" />
              </template>
              <template v-slot:append>
                <q-icon
                  name="smartphone"
                  class="cursor-pointer text-primary"
                />
              </template>
              <template v-if="!uploadFile" v-slot:label>
                {{ logoObject?.mobile?.filename }}
              </template>
            </q-file>
            <q-img
              :src="logoObject?.mobile?.logo"
              class="q-mt-md"
              style="max-width: 100%; max-height: 300px; object-fit: fill"
              fit="fill"
            />
          </q-card-section>
        </q-card>
      </div>
    </div>
    <div class="row justify-end q-pa-sm">
      <f-btn
        :label="$t('save')"
        @click="saveLogo"
        data-test="company-logo-save-btn"
      />
    </div>

    <q-dialog v-model="dialog">
      <q-card style="width: 1400px; max-width: 80vw">
        <q-toolbar class="text-white secondary-toolbar">
          <q-toolbar-title>
            <span class="text-weight-bold">{{ $t('preview') }}</span>
          </q-toolbar-title>
          <q-btn flat round dense icon="close" v-close-popup />
        </q-toolbar>

        <q-card-section
          class="q-pt-lg q-pb-lg"
          style="align-content: center; display: flex"
        >
          <q-img
            style="
              max-width: 50%;
              max-height: 50%;
              margin: 0 auto !important;
              border: 1px solid;
            "
            :src="imageUrl"
            spinner-color="white"
            fit="fill"
          />
        </q-card-section>

        <q-card-actions align="right" class="bg-white text-teal">
          <f-btn flat :label="$t('close')" v-close-popup />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import { supplierApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  setup() {
    const settings_store = useSettingStore();
    const { updateSetting } = settings_store;

    const uploadFile = ref<File | null>(null);
    const uploadFileMoblie = ref<File | null>(null);
    const dialog = ref(false);
    const logoObject = ref({
      desktop: {
        filename: 'default',
        logo: '/images/fellowpro-logo.png',
      },
      mobile: {
        filename: 'default',
        logo: '/images/fellowpro-logo.png',
      },
    }) as any;
    const handleUpload = (file: any, type = 'desktop') => {
      if (file) {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => {
          logoObject.value = {
            ...logoObject.value,
            [type]: {
              filename: file.name,
              logo: reader.result as string,
            },
          };
        };
        reader.onerror = (error: any) => {
          logError('Error converting file to base64:', error);
        };
      }
    };
    return {
      uploadFile,
      uploadFileMoblie,
      handleUpload,
      updateSetting,
      dialog,
      logoObject,
      imageUrl: ref(''),
    };
  },
  mounted() {
    this.init();
  },
  methods: {
    async init() {
      await this.fetchLogo();
    },
    async saveLogo() {
      try {
        await this.updateSetting('LOGO', JSON.stringify(this.logoObject));
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async fetchLogo() {
      try {
        const logoObject = JSON.parse(await supplierApiService.getLogo('LOGO'));
        if (logoObject) {
          this.logoObject = logoObject;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },
});
</script>
