<template>
  <div class="vendor-grouping-container">
    <div class="vendor-grouping-content">
      <div class="panel-header q-mb-md">{{ $t('vendor_id_grouping') }}</div>

      <!-- Bulk paste input -->
      <q-input
        v-model="newGroupInput"
        type="textarea"
        outlined
        dense
        :placeholder="$t('please_enter_comma_separated_values')"
        rows="2"
        :error="!!inputError"
        :error-message="inputError"
        class="q-mb-none"
        @keydown.enter.prevent="createGroup"
      />
      <div class="row justify-end q-mb-md">
        <q-btn
          color="primary"
          :label="$t('create_group')"
          unelevated
          no-caps
          @click="createGroup"
        />
      </div>

      <!-- Group cards -->
      <div
        v-for="(group, groupIndex) in groups"
        :key="group.id"
        class="group-row"
        :class="{ 'group-row--editing': editingGroupId === group.id }"
        @click="startEdit(group)"
      >
        <!-- View mode -->
        <template v-if="editingGroupId !== group.id">
          <div class="row items-center no-wrap">
            <q-badge
              :style="{ backgroundColor: 'color-mix(in srgb, var(--primary-color) 15%, white)', color: 'var(--primary-color)' }"
              class="text-weight-bold group-badge q-mr-md"
            >
              GROUP {{ groupIndex + 1 }}
            </q-badge>
            <div class="row q-gutter-xs items-center" style="flex: 1; min-width: 0; position: relative; top: 2px;">
              <q-chip
                v-for="member in group.members"
                :key="member"
                outline
                size="md"
                style="border-color: var(--primary-color); color: #6b7280 !important;"
                @click.stop
              >
                {{ member }}
              </q-chip>
            </div>
            <q-btn
              flat
              dense
              round
              size="md"
              icon="delete_outline"
              color="grey-6"
              class="q-ml-sm"
              @click.stop="deleteGroup(group.id)"
            />
          </div>
        </template>

        <!-- Edit mode -->
        <template v-else>
          <div class="row items-center q-mb-sm">
            <q-badge
              :style="{ backgroundColor: 'color-mix(in srgb, var(--primary-color) 15%, white)', color: 'var(--primary-color)' }"
              class="text-weight-bold group-badge"
            >
              GROUP {{ groupIndex + 1 }}
            </q-badge>
            <q-space />
            <q-btn
              color="primary"
              :label="$t('save')"
              unelevated
              no-caps
              padding="3px 12px"
              class="q-mr-sm"
              style="border-radius: 6px;"
              @click.stop="saveEdit(group)"
            />
            <q-btn
              outline
              color="grey-6"
              no-caps
              padding="3px 12px"
              :label="$t('cancel')"
              style="border-radius: 6px;"
              @click.stop="cancelEdit"
            />
          </div>
          <q-input
            v-model="editInput"
            type="textarea"
            outlined
            dense
            rows="2"
            @click.stop
            @keydown.enter.prevent="saveEdit(group)"
          />
        </template>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';
import { vendor_id_grouping } from 'src/constants';
import { notify } from 'src/components/notifications/notify';

interface VendorGroup {
  id: number;
  members: string[];
}

export default defineComponent({
  name: 'VendorIdGrouping',
  mounted() {
    this.initView();
  },
  data() {
    return {
      newGroupInput: '',
      inputError: '',
      groups: [] as VendorGroup[],
      editingGroupId: null as number | null,
      editInput: '',
      nextId: 1,
      vendor_id_grouping
    };
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      updateSetting,
    };
  },
  methods: {
    initView() {
      if (!this.user_settings[this.vendor_id_grouping]) {
        this.user_settings[this.vendor_id_grouping] = '[]';
      }
      if (this.user_settings[this.vendor_id_grouping]) {
        this.groups = JSON.parse(this.user_settings[this.vendor_id_grouping]);
        if (this.groups.length > 0) {
          this.nextId = Math.max(...this.groups.map((g: VendorGroup) => g.id)) + 1;
        }
      }
    },
    parseIds(input: string): string[] {
      return input
        .split(',')
        .map((s) => s.trim())
        .filter((s) => s.length > 0);
    },

    createGroup() {
      this.inputError = '';
      const members = this.parseIds(this.newGroupInput);

      if (members.length < 2) {
        notify.error(this.$t('vendor_min_two_ids'));
        return;
      }

      this.groups.push({
        id: this.nextId++,
        members,
      });
      this.newGroupInput = '';
      this.saveToServer();
    },

    startEdit(group: VendorGroup) {
      if (this.editingGroupId === group.id) return;
      this.editingGroupId = group.id;
      this.editInput = group.members.join(', ');
    },

    saveEdit(group: VendorGroup) {
      const members = this.parseIds(this.editInput);

      if (members.length < 2) {
        notify.error(this.$t('vendor_min_two_ids'));
        return;
      }

      group.members = members;
      this.editingGroupId = null;
      this.editInput = '';
      this.saveToServer();
    },

    cancelEdit() {
      this.editingGroupId = null;
      this.editInput = '';
    },

    deleteGroup(id: number) {
      this.groups = this.groups.filter((g: VendorGroup) => g.id !== id);
      this.editingGroupId = null;
      this.editInput = '';
      this.saveToServer();
    },

    async saveToServer() {
      try {
        await this.updateSetting(this.vendor_id_grouping, JSON.stringify(this.groups));
        notify.success(this.$t('MSG_SAVE'));
      } catch (e: any) {
        console.error(e);
        notify.error('Failed to save changes');
      }
    }
  },
});
</script>

