<template>
  <div>
    <input
      type="file"
      ref="fileInput"
      accept="application/pdf"
      @change="handleFileUpload"
      hidden
    />
    <div class="row items-center justify-end q-pa-sm">
      <f-btn
        :label="$t('upload_document')"
        @click="triggerFileUpload"
      />
    </div>
    <div class="row full-width justify-center">
      <iframe
        v-if="url"
        :src="url"
        title="pdf Document"
        width="90%"
        height="900px"
      ></iframe>
      <div v-else class="q-mt-lg">
        {{ $t('no_policy_statement_status') }}
      </div>
    </div>

    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { useTermAndCondtionStore } from 'src/store/Document/term_and_condtion.store';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  async mounted() {
    await this.getFile();
  },
  methods: {
    triggerFileUpload() {
      (this.$refs.fileInput as any).click();
    },
    async handleFileUpload(event: any) {
      const file = event.target.files[0];
      try {
        await this.uploadTerm(file);
        notify.success(this.$t('upload_success'));
      } catch (error) {
        logInfo(error, 'error');
      }
    },
    fileUrl(file: File | null) {
      if (file) {
        return URL.createObjectURL(file);
      }
    },
  },
  setup() {
    const term_and_condtion = useTermAndCondtionStore();
    const { uploadTerm, getFile } = term_and_condtion;
    const { loading, url } = storeToRefs(term_and_condtion);
    return {
      uploadTerm,
      loading,
      url,
      getFile,
      pdfFileUpload: ref(null as File | null),
    };
  },
});
</script>
