import { defineStore } from 'pinia';
import { supplierRegistrationReferenceDocumentsApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';

export const supplierRegistrationReferenceDocumentsStore = defineStore(
  'supplier_registration_reference_documents_store',
  {
    state: () => ({
      loading: false,
      fileList: [] as dynamicObj,
    }),
    actions: {
      async uploadReferenceDocument(file: any) {
        try {
          const response =
            await supplierRegistrationReferenceDocumentsApiService.upload(file);
          if (response.success === false) {
            throw response;
          }
          return response as dynamicObj;
        } catch (error) {
          logError(error);
        }
      },
      async getFiles() {
        try {
          const response =
            await supplierRegistrationReferenceDocumentsApiService.getFile();
          if (response.success) {
            this.fileList = response.data;
          } else {
            this.fileList = [];
          }
        } catch (error) {
          logError(error);
        }
      },
    },
  },
);
