<template>
  <div class="settings-card">
    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{
          $t('supplier_portal_additional_invitation_fields')
        }}</span>
      </div>
      <div class="settings-toggle-selects">
        <q-select
          v-if="user_settings[supplier_portal_additional_fields_preference]"
          outlined
          class="back-white"
          dense
          v-model="supplierFields"
          multiple
          :options="field_options"
          :loading="loading"
          :label="$t('fields')"
          style="min-width: 250px"
          emit-value
          map-options
          @update:model-value="handleUpdateAdditionalFields"
        />
      </div>
      <div class="settings-toggle-actions">
        <f-toggle
          size="xs"
          v-model="
            user_settings[supplier_portal_additional_fields_preference]
          "
          @update:model-value="handleTogglePreference"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import {
  supplier_portal_additional_fields_preference,
  supplier_portal_additional_fields,
} from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions';
import { docFieldsApiService } from 'src/services';
export default defineComponent({
  el: '#app',
  data() {
    return {
      supplier_portal_additional_fields_preference,
      supplier_portal_additional_fields,
      field_setting: ref([]),
      field_options: ref([]),
      supplierFields: ref() as unknown as string | dynamicObj[],
    };
  },
  watch: {
    loading_settings: {
      handler: async function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        if (this.user_settings[supplier_portal_additional_fields_preference]) {
          await this.getDefaultFields();
          this.initView();
        }
      },
    },
  },
  mounted: async function () {
    try {
      this.loading = true;
      this.initView();
      await this.getDefaultFields();
    } catch (err) {
      const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
      notify.error(msg);
      logError(err);
    } finally {
      this.loading = false;
    }
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;
    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      updateSetting,
    };
  },
  methods: {
    initView() {
      if (
        !this.user_settings[this.supplier_portal_additional_fields_preference]
      ) {
        this.user_settings[this.supplier_portal_additional_fields_preference] =
          false;
      }
      // get supplier portal additional fields
      this.supplierFields = this.user_settings[
        this.supplier_portal_additional_fields
      ] as string;
      if (this.supplierFields) {
        this.supplierFields = JSON.parse(this.supplierFields);
      }
    },
    async handleUpdateAdditionalFields(val: string) {
      try {
        await this.updateSetting(
          supplier_portal_additional_fields,
          JSON.stringify(val),
        );
        this.user_settings[supplier_portal_additional_fields] =
          JSON.stringify(val);
        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },
    async handleTogglePreference(val: boolean) {
      try {
        if (val) {
          this.loading = true;
          this.initView();
          await this.getDefaultFields();
        }
        this.updateSetting(supplier_portal_additional_fields_preference, val);
        this.user_settings[supplier_portal_additional_fields_preference] = val;
        notify.success(this.$t('save_successfully'));
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.loading = false;
      }
    },
    async getDefaultFields() {
      try {
        const data = {
          doc_type: 'SUPPLIER_M3',
        };
        const response = await docFieldsApiService.getFieldSettingsByType(data);
        this.field_setting = response.field_setting;
        if (this.field_setting.length > 0) {
          const fields = this.field_setting[0] as dynamicObj;
          this.field_options = fields?.rows?.map((field: dynamicObj) => {
            return {
              label: field[0].title,
              value: field[0].field_name,
            };
          });
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },
});
</script>
